"""Write generated content into the LaTeX paper without hand-editing it.

Every insertion sits between a pair of marker comments::

    %% AUTOGEN:<key> BEGIN - generated by sensorsim; edits here are overwritten
    ...
    %% AUTOGEN:<key> END

On the first run a block goes in at a named anchor. On later runs the text
between its markers is replaced, so running again never duplicates anything.
The ``.tex`` file is backed up before every write, and numbers in the
generated prose are macros from ``generated/proposed_numbers.tex``. A number
in the text therefore cannot drift from the table it came from.
"""

from __future__ import annotations

import re
import shutil
import time
import zipfile
from pathlib import Path

PAPER_DIR = Path("paper/overleaf")
DEFAULT_TEX = PAPER_DIR / "main.tex"

_LATEX_SPECIALS = {
    "\\": r"\textbackslash{}",
    "&": r"\&",
    "%": r"\%",
    "$": r"\$",
    "#": r"\#",
    "_": r"\_",
    "{": r"\{",
    "}": r"\}",
    "~": r"\textasciitilde{}",
    "^": r"\textasciicircum{}",
}


def escape(text: str) -> str:
    """Escape LaTeX special characters in plain text."""
    return "".join(_LATEX_SPECIALS.get(ch, ch) for ch in str(text))


def _markers(key: str) -> tuple[str, str]:
    return (f"%% AUTOGEN:{key} BEGIN - generated by sensorsim; edits here are overwritten",
            f"%% AUTOGEN:{key} END")


def upsert_block(text: str, key: str, body: str, anchor: str | tuple[str, ...], where: str = "before") -> str:
    """Replace the block ``key`` if present, otherwise insert it at ``anchor``.

    ``anchor`` may be a tuple of alternatives; the first one present is used.
    """
    begin, end = _markers(key)
    block = f"{begin}\n{body.rstrip()}\n{end}\n"
    pattern = re.compile(re.escape(f"%% AUTOGEN:{key} BEGIN") + r".*?" + re.escape(end) + r"\n?", re.S)
    if pattern.search(text):
        return pattern.sub(lambda _: block, text, count=1)
    anchors = (anchor,) if isinstance(anchor, str) else anchor
    index, anchor = next(((text.find(a), a) for a in anchors if a in text), (-1, anchors[0]))
    if index < 0:
        raise ValueError(f"anchor not found for block {key!r}: {anchors!r}")
    if where == "after":
        line_end = text.find("\n", index + len(anchor))
        index = len(text) if line_end < 0 else line_end + 1
        return text[:index] + block + text[index:]
    # "before": start of the anchor's line, so the block never splits a line
    line_start = text.rfind("\n", 0, index) + 1
    return text[:line_start] + block + "\n" + text[line_start:]


def remove_block(text: str, key: str) -> str:
    begin, end = _markers(key)
    pattern = re.compile(re.escape(f"%% AUTOGEN:{key} BEGIN") + r".*?" + re.escape(end) + r"\n?\n?", re.S)
    return pattern.sub("", text)


def backup(tex: Path) -> Path:
    stamp = time.strftime("%Y%m%d-%H%M%S")
    target = tex.with_name(f"{tex.name}.bak-{stamp}")
    n = 1
    while target.exists():
        target = tex.with_name(f"{tex.name}.bak-{stamp}-{n}")
        n += 1
    shutil.copy2(tex, target)
    return target


def write_blocks(tex: str | Path, blocks: list[tuple[str, str, str, str]]) -> dict[str, str]:
    """Apply ``(key, body, anchor, where)`` blocks to ``tex`` with one backup."""
    tex = Path(tex)
    original = tex.read_text(encoding="utf-8")
    text = original
    for key, body, anchor, where in blocks:
        text = upsert_block(text, key, body, anchor, where)
    if text == original:
        return {"tex": tex.as_posix(), "backup": "", "changed": "no"}
    saved = backup(tex)
    tex.write_text(text, encoding="utf-8")
    return {"tex": tex.as_posix(), "backup": saved.as_posix(), "changed": "yes"}


def rebuild_overleaf_zip(paper_dir: str | Path = PAPER_DIR, out: str | Path = "paper/SensorSim_overleaf.zip") -> Path:
    """main.tex + refs.bib + figures/ + generated/, ready to upload to Overleaf."""
    paper_dir = Path(paper_dir)
    out = Path(out)
    with zipfile.ZipFile(out, "w", zipfile.ZIP_DEFLATED) as zf:
        for name in ("main.tex", "refs.bib"):
            if (paper_dir / name).exists():
                zf.write(paper_dir / name, name)
        for sub in ("figures", "generated"):
            for f in sorted((paper_dir / sub).glob("*")):
                if f.is_file() and f.suffix.lower() in {".png", ".pdf", ".jpg", ".tex"}:
                    zf.write(f, f"{sub}/{f.name}")
    return out


