PREAMBLE = r"""% NAG (this work): arm names and every number quoted from the NAG study.
\newcommand{\NCDCE}{\texttt{nc\_dce}}
\newcommand{\GESR}{\texttt{g\_esrgan}}
\newcommand{\NAGarm}{\texttt{nag}}
\newcommand{\ZDCE}{\texttt{zero\_dce}}
\newcommand{\RESR}{\texttt{real\_esrgan}}
\input{generated/proposed_numbers}"""

ABSTRACT = r"""\input{generated/nag_abstract}"""

CONTRIBUTION = r"""We add a fifth contribution:
(v)~NAG, an enhancement method that extends two published networks with a noise
map propagated in closed form. It has three parts: a noise-conditioned curve
estimator trained without references (NC-DCE), a guided filter whose strength
follows the propagated noise (VP-denoise), and a Wiener gate with low-pass
back-projection that limits the detail a generative super-resolution network
may add (G-ESRGAN). NAG is evaluated with the same instrument, sweep and
statistics as the classical arms (Section~\ref{sec:nag})."""

CONCLUSION = r"""\input{generated/nag_conclusion}"""

SECTION = r"""% =============================================================================
\section{Proposed Method: Noise-Aware Guarded Enhancement}\label{sec:nag}
% =============================================================================

The pilot measures existing arms. This section uses the same instrument to
develop a new one. We start from two published learned methods, each of which
fails in a way the testbench can see.
Zero-DCE~\cite{guo2020zerodce} brightens an image with eight learned quadratic
curves per pixel and is trained without reference images. None of its four
training losses can observe noise, so it lifts a noisy shadow as strongly as a
clean one.
Real-ESRGAN~\cite{wang2021realesrgan} restores resolution with a generator that
also produces detail the measurement does not contain, which is the substitution
behaviour H2 and H3 are about.
NAG (noise-aware guarded enhancement) keeps both networks and gives every stage
the same additional input: an estimate of how much of each pixel is noise.

\subsection{A Noise Map Carried Through the Pipeline}

The forward model of Section~\ref{sec:model} is Poisson--Gaussian, and every arm
already receives the capture record. For gain-corrected linear signal $u$ at
photon scale $\alpha$, binning $b$, full well $F$, read noise $\sigma_r$ over a
DN span $S$ and bit depth $B$, the variance is
\begin{equation}
\mathrm{var}(u) = \frac{u}{\alpha F b^2}
 + \Big(\frac{\sigma_r}{\alpha S b^2}\Big)^{2}
 + \frac{(\alpha^{-1} q)^2}{12},
\label{eq:nagvar}
\end{equation}
where $q = 1/(2^{B}-1)$ is the quantisation step, plus small dark-current and
PRNU terms. White balance scales a channel's
standard deviation by its gain. Demosaicing an RGGB mosaic averages neighbouring
samples, which scales the standard deviation by $3/4$ for R and B and by
$\sqrt{3/4}$ for G. Any monotone curve $T$ is applied through the symmetric secant
$\sigma' = |T(x+\sigma) - T(x-\sigma)|/2$, which remains bounded near black, where
the sRGB slope is steep. On flat fields, across \nagNoiseCases\ combinations of
sensor condition, signal level and colour channel, the predicted map matched
the measured standard deviation to within \nagNoiseMaxErr\
(Table~\ref{tab:nagnoise}). For uploaded files, which have
no capture record, a blind noise-level function is estimated from the image
instead.

\subsection{NC-DCE: Noise-Conditioned Curves}

NC-DCE uses the Zero-DCE network~\cite{guo2020zerodce} with the luma noise map
as a fourth input channel. The weights are initialised from the published
checkpoint, with the new channel's weights set to zero. Each iteration
$\mathrm{LE}_n = \mathrm{LE}_{n-1} + r_n(\mathrm{LE}_{n-1}^2 - \mathrm{LE}_{n-1})$
has a closed-form derivative, so the slope of the whole curve is
\begin{equation}
s = \prod_{n=1}^{8}\big(1 + r_n(2\,\mathrm{LE}_{n-1} - 1)\big),
\qquad \sigma_{\mathrm{out}} = |s|\,\sigma .
\end{equation}
Brightening scales signal and noise together, so in textured regions it costs no
SNR. Noise is what a viewer sees in flat regions. We therefore add one term to
the four Zero-DCE losses:
\begin{equation}
\mathcal{L}_{\mathrm{noise}} = \frac{1}{\tau^2}\,
\mathbb{E}\Big[w_{\mathrm{flat}}\,
\mathrm{relu}\big(|s|\sigma - \max(\sigma, \tau)\big)^2\Big],
\end{equation}
with $\tau = 2/255$ and $w_{\mathrm{flat}} = 1 - \gamma$, where $\gamma$ is the
gate defined below. Every arm receives a gain-matched frame, so the exposure
term is one-sided: it lifts regions below the target level and never darkens a
correctly exposed region. Training needs no references. It used
\nagTrainSamples\ procedurally generated scenes (seeds disjoint from the test
corpus) degraded at random severities, for \nagTrainEpochs\ epochs
(\nagTrainSeconds~s on one laptop GPU).

\subsection{VP-Denoise and G-ESRGAN}

After the curves, a self-guided filter~\cite{he2013guided} runs with a per-pixel
regulariser $\epsilon = (1.5\,\sigma_{\mathrm{out}})^2$. It therefore smooths only
where the curves amplified noise. The detail Real-ESRGAN adds,
$d = \mathrm{SR}(y) - U(y)$, is then scaled by a Wiener-style gate. The
four-neighbour Laplacian has noise gain 20, so for local high-frequency energy
$E_y$ of the measured frame,
\begin{equation}
\gamma = \mathrm{clip}\Big(\frac{E_y - 20\,\sigma^2}{E_y + \epsilon}, 0, 1\Big),
\qquad x = U(y) + \gamma\, d ,
\end{equation}
which is the fraction of local detail energy that is signal. Three iterations
of low-pass back-projection~\cite{irani1991improving},
$x \leftarrow x + U\big(G * (y - D(x))\big)$, follow. Here $D$ is the recorded
capture operator (PSF, then binning) and $G$ is a small Gaussian that keeps the
measurement's noise out of the update.

\subsection{Results}

The study reuses the pilot's corpus, sweep, seed and fourteen metrics. Its bank
adds the two published learned arms (\ZDCE, \RESR), the three proposed arms
(\NCDCE, \GESR, \NAGarm), five ablations and a fine-tuned \ZDCE\ control,
\nagObservations\ measured observations in total. The pilot's own table is
untouched. Every comparison below pairs two arms on the same frame and
condition (21 pairs) and uses a Wilcoxon signed-rank test.
The text that states a direction is generated from the same numbers as the
tables.

\input{generated/proposed_results}
"""


#: The paper puts a rule comment above each section heading; insert above the
#: rule so a section keeps its own banner. Plain heading as a fallback.
RULE = "% " + "=" * 77 + "\n"
DISCUSSION = (RULE + r"\section{Discussion}", r"\section{Discussion}")


def update_paper_with_nag(tex: str | Path = DEFAULT_TEX, rebuild_zip: bool = True) -> dict[str, str]:
    """Insert or refresh every NAG block in the paper."""
    blocks = [
        ("nag-preamble", PREAMBLE, r"\newcommand{\NRQ}", "after"),
        ("nag-abstract", ABSTRACT, r"\end{abstract}", "before"),
        ("nag-contribution", CONTRIBUTION, "paper is regenerated from one command.", "after"),
        ("nag-section", SECTION, DISCUSSION, "before"),
        ("nag-conclusion", CONCLUSION, r"\section*{Acknowledgment}", "before"),
    ]
    tex = Path(tex)
    _ensure_bib(tex.parent / "refs.bib")
    result = write_blocks(tex, blocks)
    if rebuild_zip:
        result["zip"] = rebuild_overleaf_zip(tex.parent).as_posix()
    return result


BIB_ADDITIONS = {
    "he2013guided": """@article{he2013guided,
  author  = {He, Kaiming and Sun, Jian and Tang, Xiaoou},
  title   = {Guided Image Filtering},
  journal = {IEEE Trans. Pattern Anal. Mach. Intell.},
  volume  = {35},
  number  = {6},
  pages   = {1397--1409},
  year    = {2013}
}""",
    "irani1991improving": """@article{irani1991improving,
  author  = {Irani, Michal and Peleg, Shmuel},
  title   = {Improving Resolution by Image Registration},
  journal = {CVGIP: Graphical Models and Image Processing},
  volume  = {53},
  number  = {3},
  pages   = {231--239},
  year    = {1991}
}""",
}


def _ensure_bib(bib: Path) -> None:
    """Append the two references the NAG section adds, if they are missing."""
    if not bib.exists():
        return
    text = bib.read_text(encoding="utf-8")
    missing = [entry for key, entry in BIB_ADDITIONS.items() if f"{{{key}," not in text]
    if missing:
        bib.write_text(text.rstrip() + "\n\n" + "\n\n".join(missing) + "\n", encoding="utf-8")
